CREATE TABLE APP_USER(user_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR2(120) NOT NULL,email VARCHAR2(180) NOT NULL UNIQUE,phone VARCHAR2(30),password_hash VARCHAR2(255) NOT NULL,role VARCHAR2(20) DEFAULT 'PARTICIPANT' NOT NULL,CONSTRAINT ck_user_role CHECK(role IN ('ADMIN','ORGANIZER','PARTICIPANT')));
CREATE TABLE EVENT(event_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR2(180) NOT NULL,type VARCHAR2(80) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,status VARCHAR2(20) DEFAULT 'PLANNED' NOT NULL,CONSTRAINT ck_event_dates CHECK(end_date>=start_date),CONSTRAINT ck_event_status CHECK(status IN ('PLANNED','ACTIVE','COMPLETED','CANCELLED')));
CREATE TABLE VENUE(venue_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR2(120) NOT NULL,capacity NUMBER(8) NOT NULL,location VARCHAR2(180) NOT NULL,CONSTRAINT ck_venue_capacity CHECK(capacity>0));
CREATE TABLE SESSION(session_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_id NUMBER NOT NULL,title VARCHAR2(180) NOT NULL,start_time TIMESTAMP NOT NULL,end_time TIMESTAMP NOT NULL,venue_id NUMBER NOT NULL,CONSTRAINT fk_session_event FOREIGN KEY(event_id) REFERENCES EVENT(event_id),CONSTRAINT fk_session_venue FOREIGN KEY(venue_id) REFERENCES VENUE(venue_id),CONSTRAINT ck_session_time CHECK(end_time>start_time));
CREATE TABLE RESOURCE(resource_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR2(120) NOT NULL,type VARCHAR2(80) NOT NULL,quantity_total NUMBER(8) NOT NULL,location VARCHAR2(180),CONSTRAINT ck_resource_qty CHECK(quantity_total>=0));
CREATE TABLE REGISTRATION(registration_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_id NUMBER NOT NULL,user_id NUMBER NOT NULL,registration_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,status VARCHAR2(20) DEFAULT 'REGISTERED' NOT NULL,CONSTRAINT uq_registration UNIQUE(event_id,user_id),CONSTRAINT fk_reg_event FOREIGN KEY(event_id) REFERENCES EVENT(event_id),CONSTRAINT fk_reg_user FOREIGN KEY(user_id) REFERENCES APP_USER(user_id),CONSTRAINT ck_reg_status CHECK(status IN ('REGISTERED','CANCELLED','ATTENDED')));
CREATE TABLE PAYMENT(payment_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,registration_id NUMBER NOT NULL,amount NUMBER(10,2) NOT NULL,payment_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,status VARCHAR2(20) DEFAULT 'PENDING' NOT NULL,CONSTRAINT fk_payment_reg FOREIGN KEY(registration_id) REFERENCES REGISTRATION(registration_id),CONSTRAINT ck_payment_amount CHECK(amount>=0),CONSTRAINT ck_payment_status CHECK(status IN ('PENDING','PAID','FAILED','REFUNDED')));
CREATE TABLE RESOURCE_ALLOCATION(allocation_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_id NUMBER NOT NULL,session_id NUMBER,resource_id NUMBER NOT NULL,quantity NUMBER(8) NOT NULL,allocated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT fk_alloc_event FOREIGN KEY(event_id) REFERENCES EVENT(event_id),CONSTRAINT fk_alloc_session FOREIGN KEY(session_id) REFERENCES SESSION(session_id),CONSTRAINT fk_alloc_resource FOREIGN KEY(resource_id) REFERENCES RESOURCE(resource_id),CONSTRAINT ck_alloc_qty CHECK(quantity>0));
CREATE INDEX idx_session_venue_time ON SESSION(venue_id,start_time,end_time);
CREATE INDEX idx_registration_event ON REGISTRATION(event_id);
CREATE INDEX idx_allocation_resource ON RESOURCE_ALLOCATION(resource_id);